typedef struct {
    uint64_t key;
    z_t1668_t value;
} z_t2078_entry_t;

typedef struct z_t2078_t {
    uint32_t length;
    uint32_t capacity;
    uint32_t* indices;
    z_t2078_entry_t* entries;
} z_t2078_t;

