    _this->entries = (z_t1153_entry_t*)z_xrealloc(_this->entries,
        (size_t)z_t1153_entries_cap(_new_cap) * sizeof(z_t1153_entry_t));
    _this->capacity = _new_cap;
    free(_this->indices);
